    if traces_endpoint := os.environ.get("OTEL_EXPORTER_OTLP_TRACES_ENDPOINT"):
        return traces_endpoint

    if base_endpoint := os.environ.get("OTEL_EXPORTER_OTLP_ENDPOINT"):
        return base_endpoint.rstrip("/") + OTLP_TRACES_PATH

    return None


